#[test]
fn sqlite_snapshot_semio_animation_rejects_variant_shape_relationships_and_limits(){let original=project(&fixture());for change in 0..5{let mut db=original.clone();match change{0=>db.table_mut("semio_animation_weight").unwrap().rows[0].values[1]=SqliteValue::Integer(999),1=>db.table_mut("semio_animation_weight").unwrap().rows[0].values[2]=SqliteValue::Integer(99),2=>db.table_mut("semio_animation_channel").unwrap().rows[0].values[5]=SqliteValue::Text("unexpected".into()),3=>{db.table_mut("semio_animation_vector3").unwrap().rows.remove(0);},_=>db.table_mut("semio_animation_keyframe").unwrap().rows[0].values[4]=SqliteValue::Text("vector3".into())}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_rows:1,max_value_bytes:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(SemioAnimationSnapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
#[test]
fn sqlite_snapshot_semio_animation_independent_variant_join_and_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(db.query('SELECT name FROM semio_animation_timeline ORDER BY ordinal').all().map(r=>r.name===null?'NULL':r.name).slice(0,2).join(',')!=='NULL,')throw Error('optional names');if(db.query('SELECT value FROM semio_animation_scalar WHERE id=1').get().value!==-2.5)throw Error('scalar');db.query('UPDATE semio_animation_scalar SET value=3.25,value_ieee754_bits=4614500768194494464 WHERE id=1').run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let restored=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();expected.timelines[0].channels[0].keyframes[0].value=AnimValue::Scalar{value:3.25};assert_eq!(restored,expected);}

